// The tDevice passthrough-hack accessor implementations declared in common_public.h.
//
// The TDEV_ACCESSOR_* macros below reuse the EXACT names of the declaration macros from the header
// (which are #undef'ed there after use) and are re-#defined to take (name, expr) [ENUM: (name, expr,
// typ)] so the declaration and the definition share one signature pattern and only the field
// expression comes from this side. KEEP these signatures in sync with the declaration-side macros in
// common_public.h; the header prototypes are the exported API boundary over the DLL/.so.
//
// Setters assign the field AND OR the source into the passThroughHacks.hackSources provenance word
// (latching: bits accumulate, cleared only by the tDevice zero-init at discovery; no M_INLINE: these
// are real exported symbols). Getters are plain field reads.

#include "common_public.h"
#include "tdevice_accessors_impl.c"

